"""Bloom filter implementations (R1, R4-R6, R8, R10, R12).

StandardBloomFilter : classic BF with an integer number k of hash functions.
RationalBloomFilter : RBF of Definition 2 / Algorithm 1 - floor(k) always-
                      applied hash functions plus one probabilistically
                      activated hash function with activation probability
                      p_activation = k - floor(k), decided deterministically
                      per input from Hr(x) (same rule for insert and query,
                      which preserves the no-false-negative property for
                      floor(k) >= 1, Lemma 1).
"""

from hash_utils import hash_pair, indices


class BitArray:
    """All-zero bit array of length m (R1); m must be a power of two so that
    index computation is the binary AND of Eqn 3 (R8)."""

    __slots__ = ("m", "buf")

    def __init__(self, m):
        if m <= 0 or (m & (m - 1)) != 0:
            raise ValueError("m must be a power of two (Eqn 3 AND trick)")
        self.m = m
        self.buf = bytearray((m + 7) >> 3)

    def set(self, i):
        if not 0 <= i < self.m:
            raise IndexError("bit index out of range: %r" % (i,))
        self.buf[i >> 3] |= 1 << (i & 7)

    def get(self, i):
        if not 0 <= i < self.m:
            raise IndexError("bit index out of range: %r" % (i,))
        return (self.buf[i >> 3] >> (i & 7)) & 1

    def ones(self):
        return sum(bin(b).count("1") for b in self.buf)

    def fraction_of_zeros(self):
        return 1.0 - self.ones() / self.m


class _Base:
    def __init__(self, m):
        self.bits = BitArray(m)
        self.m = m
        self.n_inserted = 0

    def fraction_of_zeros(self):
        return self.bits.fraction_of_zeros()


class StandardBloomFilter(_Base):
    """Standard BF: k integer hash functions H_1..H_k (R1, R10)."""

    def __init__(self, m, k, seed_h1=0, seed_h2=0x9E3779B9):
        super().__init__(m)
        self.k = int(k)
        if self.k < 1:
            raise ValueError("standard BF needs k >= 1")
        self.seed_h1 = seed_h1
        self.seed_h2 = seed_h2

    def _idxs(self, x):
        h1, h2 = hash_pair(x, self.seed_h1, self.seed_h2)
        return indices(h1, h2, self.m, self.k)   # H_0..H_k

    def insert(self, x):
        idxs = self._idxs(x)
        b = self.bits
        for i in range(1, self.k + 1):
            b.set(idxs[i])
        self.n_inserted += 1

    def query(self, x):
        idxs = self._idxs(x)
        b = self.bits
        for i in range(1, self.k + 1):
            if not b.get(idxs[i]):
                return False
        return True

    def checked_indices(self, x):
        """Indices checked by a membership query (diagnostic for C1)."""
        return self._idxs(x)[1:self.k + 1]


class RationalBloomFilter(_Base):
    """RBF (Definition 2, Algorithm 1): floor(k) hashes + 1 probabilistically
    activated hash with p_activation = k - floor(k) (R4)."""

    def __init__(self, m, k, seed_h1=0, seed_h2=0x9E3779B9):
        super().__init__(m)
        self.k = float(k)
        if self.k < 0:
            raise ValueError("k must be >= 0")
        self.floor_k = int(self.k)
        self.p_activation = self.k - self.floor_k
        self.seed_h1 = seed_h1
        self.seed_h2 = seed_h2

    def _plan(self, x):
        """Indices H_0..H_{floor(k)+1} and the deterministic activation bit."""
        h1, h2 = hash_pair(x, self.seed_h1, self.seed_h2)
        idxs = indices(h1, h2, self.m, self.floor_k + 1)   # up to H_{floor+1}
        if self.floor_k >= 1:
            # Algorithm 1 line 4: no extra calculation if Hr = H_floor(k) (A5)
            hr = idxs[self.floor_k]
            extra = idxs[self.floor_k + 1]
        else:
            # k < 1: no always-applied hash exists; fall back to H_0 = h1 & (m-1)
            hr = idxs[0]
            extra = idxs[1]
        activated = hr < self.p_activation * self.m          # Algorithm 1 line 5
        return idxs, activated, extra

    def insert(self, x):
        idxs, activated, extra = self._plan(x)
        b = self.bits
        for i in range(1, self.floor_k + 1):
            b.set(idxs[i])
        if activated:
            b.set(extra)
        self.n_inserted += 1

    def query(self, x):
        # same deterministic activation rule as insert (R6, Lemma 1)
        idxs, activated, extra = self._plan(x)
        b = self.bits
        for i in range(1, self.floor_k + 1):
            if not b.get(idxs[i]):
                return False
        if activated and not b.get(extra):
            return False
        return True

    def checked_indices(self, x):
        idxs, activated, extra = self._plan(x)
        out = idxs[1:self.floor_k + 1]
        if activated:
            out = out + [extra]
        return out

    def activation_frequency(self, elements):
        """Observed fraction of elements for which the extra hash fires."""
        if not elements:
            return 0.0
        return sum(1 for x in elements if self._plan(x)[1]) / len(elements)

